// seed: tests/seed.spec.ts (гость) · прод, только просмотр: не-GET запросы блокируются; объявления — из кэша сайта, не хардкод.
import { test, expect } from '@playwright/test';
import {
  blockWrites, openListing, cardIds, viewedCategories, readCatalog, pickRoute, expectOrder, cityIsUnambiguous,
} from './similar.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('«עסקים נוספים שעשויים לעניין אותך» — гость', () => {
  test('Новый гость: та же категория → тот же город → остальные #02706d @desktop @prod-safe', async ({ page }) => {
    await blockWrites(page);
    await page.goto('/');
    const catalog = await readCatalog(page);
    const perCat = new Map<string, number>();
    catalog.forEach((b) => b.category && perCat.set(b.category, (perCat.get(b.category) || 0) + 1));
    const current = catalog.find(
      (b) =>
        b.category && perCat.get(b.category)! >= 2 && perCat.get(b.category)! <= 4 &&
        cityIsUnambiguous(catalog, b.city) &&
        catalog.filter((x) => x.city === b.city && x.category !== b.category).length >= 2,
    );
    expect(current, 'в каталоге есть объявление: маленькая категория + город с другими объявлениями').toBeTruthy();

    await openListing(page, current!.id);
    expect(await viewedCategories(page), 'история = [категория объявления]').toEqual([current!.category]);
    const ranks = expectOrder(catalog, current!, [current!.category!], await cardIds(page));
    expect(ranks[0], 'первая карточка — та же категория').toBe(0);
    expect(ranks, 'есть карточки того же города').toContain(100);
  });

  test('Маршрут A → B → C: недавние категории в блоке, новая первой #02706d @android @prod-safe', async ({ page }) => {
    await blockWrites(page);
    await page.goto('/');
    const catalog = await readCatalog(page);
    const route = pickRoute(catalog);
    for (const biz of route) await openListing(page, biz.id);
    const [a, b, c] = route;

    const history = await viewedCategories(page);
    expect(history, 'история: самая новая категория первой').toEqual([c.category, b.category, a.category]);
    const ranks = expectOrder(catalog, c, history, await cardIds(page));
    expect(ranks[0], 'первая карточка — категория C').toBe(0);
    expect(ranks, `в блоке есть категория B («${b.category}»)`).toContain(1);
    expect(ranks, `в блоке есть категория A («${a.category}»)`).toContain(2);
  });

  test('Повторное открытие категории поднимает её в начало истории без дубля #02706d @desktop @prod-safe', async ({ page }) => {
    await blockWrites(page);
    await page.goto('/');
    const catalog = await readCatalog(page);
    const a = catalog.find((x) => x.category)!;
    const b = catalog.find((x) => x.category && x.category !== a.category)!;
    await openListing(page, a.id);
    await openListing(page, b.id);
    await openListing(page, a.id);
    expect(await viewedCategories(page)).toEqual([a.category, b.category]);
  });
});
